package com.warehouse.twin.controller;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.warehouse.twin.common.Result; import com.warehouse.twin.entity.*; import com.warehouse.twin.service.*; import com.warehouse.twin.websocket.WarehouseWebSocketHandler; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/person-state")
public class PersonStateController {private final PersonStateService s;private final AlarmService alarms;private final WarehouseWebSocketHandler socket;public PersonStateController(PersonStateService s,AlarmService a,WarehouseWebSocketHandler w){this.s=s;alarms=a;socket=w;}
    @PostMapping public Result<PersonState> create(@RequestBody PersonState p){if(p.getState()==null)throw new IllegalArgumentException("人员状态不能为空");if(p.getTimestamp()==null)p.setTimestamp(LocalDateTime.now());s.save(p);if((p.getRiskScore()!=null&&p.getRiskScore().compareTo(new BigDecimal("0.75"))>=0)||Set.of("FATIGUE","DISTRACTED","HIGH_RISK").contains(p.getState())){Alarm a=new Alarm();a.setAlarmType("PERSON_STATE_"+p.getState());a.setLocation(p.getCameraId());a.setLevel(p.getRiskScore()!=null&&p.getRiskScore().doubleValue()>.9?"CRITICAL":"HIGH");a.setTriggerTime(p.getTimestamp());a.setStatus("PENDING");a.setRemark("人员 "+p.getPersonId()+" 状态风险");alarms.save(a);socket.broadcast(Map.of("type","person_alarm","data",a));}return Result.ok(p);}
    @GetMapping public Result<List<PersonState>> list(){return Result.ok(s.list(Wrappers.<PersonState>lambdaQuery().orderByDesc(PersonState::getTimestamp).last("limit 200")));}}
